public interface ISoftDeletable
{
    bool IsDeleted { get; set; }
    DateTime? DeletedAt { get; set; }
}

public class Article : ISoftDeletable
{
    public int Id { get; set; }
    public string Title { get; set; } = "";
    public bool IsDeleted { get; set; }
    public DateTime? DeletedAt { get; set; }
}

protected override void OnModelCreating(ModelBuilder b)
{
    // One filter, applied to every implementing entity
    foreach (var type in b.Model.GetEntityTypes()
                 .Where(t => typeof(ISoftDeletable).IsAssignableFrom(t.ClrType)))
    {
        var param = Expression.Parameter(type.ClrType, "e");
        var body = Expression.Not(Expression.Property(param, nameof(ISoftDeletable.IsDeleted)));
        b.Entity(type.ClrType).HasQueryFilter(Expression.Lambda(body, param));
    }

    // Survives soft delete: same email reusable after deletion
    b.Entity<Article>().HasIndex(a => a.Title)
        .IsUnique()
        .HasFilter("[IsDeleted] = 0");
}

public override async Task<int> SaveChangesAsync(CancellationToken ct = default)
{
    foreach (var entry in ChangeTracker.Entries<ISoftDeletable>())
    {
        if (entry.State == EntityState.Deleted)
        {
            entry.State = EntityState.Modified;      // don't remove the row
            entry.Entity.IsDeleted = true;
            entry.Entity.DeletedAt = DateTime.UtcNow;
        }
    }
    return await base.SaveChangesAsync(ct);
}

